          totalTiles: 1,
          tileX: 0,
          tileY: 0,
          tileWidth: unpackRes.width,
          tileHeight: unpackRes.height,
          haloSize: 0,
          sensorX: 0,
          sensorY: 0,
          sensorWidth: unpackRes.width,
          sensorHeight: unpackRes.height
